<?php
$member=$history['member']; $type=$history['type'];
$labels=['subscriptions'=>'Historique des abonnements','payments'=>'Historique des paiements d’abonnement','attendance'=>'Historique des passages'];
$title=$labels[$type]; $subtitle='Données enregistrées pour le membre.'; $section='members'; require __DIR__.'/management_header.php';
$url=static fn(int $page): string => 'member_history?'.http_build_query(['id'=>(int)$member['id'],'type'=>$type,'p'=>$page]);
?>
<section class="card management-table"><div class="card-head"><div><h3><?= e($member['first_name'].' '.$member['last_name']) ?></h3><p>Carte <?= e($member['card_number'] ?: 'non attribuée') ?> · <?= (int)$history['total'] ?> résultat(s)</p></div><a class="text-link" href="member_profile?id=<?= (int)$member['id'] ?>">← Fiche membre</a></div>
<div class="table-scroll"><table>
<?php if ($type==='subscriptions'): ?><thead><tr><th>FORMULE</th><th>DÉBUT</th><th>FIN</th><th>STATUT ACTUEL</th><th>DÉTAILS</th></tr></thead><tbody><?php foreach ($history['rows'] as $row): $state=$row['status']==='active' && $row['end_date']<date('Y-m-d') ? 'Expiré' : ($row['status']==='active' && $row['start_date']>date('Y-m-d') ? 'À venir' : (['active'=>'Actif','frozen'=>'Gelé','cancelled'=>'Annulé'][$row['status']] ?? $row['status'])); ?><tr><td><?= e($row['plan']) ?></td><td><?= e(date('d/m/Y',strtotime($row['start_date']))) ?></td><td><?= e(date('d/m/Y',strtotime($row['end_date']))) ?></td><td><?= e($state) ?></td><td><a class="text-link" href="subscription_detail?id=<?= (int)$row['id'] ?>">Détails</a></td></tr><?php endforeach; ?></tbody>
<?php elseif ($type==='payments'): ?><thead><tr><th>DATE</th><th>MONTANT INITIAL</th><th>REMBOURSÉ</th><th>MOYEN</th><th>ABONNEMENT</th><th>REÇU</th></tr></thead><tbody><?php foreach ($history['rows'] as $row): ?><tr><td><?= e(date('d/m/Y H:i',strtotime($row['paid_at']))) ?></td><td><?= e(dt($row['amount'])) ?></td><td><?= e(dt($row['refunded'])) ?></td><td><?= e(ucfirst($row['method'])) ?></td><td><?= $row['subscription_id'] ? '#'.(int)$row['subscription_id'] : '—' ?></td><td><a class="text-link" href="receipt?id=<?= (int)$row['id'] ?>">Reçu</a></td></tr><?php endforeach; ?></tbody>
<?php else: ?><thead><tr><th>DATE</th><th>RÉSULTAT</th></tr></thead><tbody><?php foreach ($history['rows'] as $row): ?><tr><td><?= e(date('d/m/Y H:i',strtotime($row['checked_in_at']))) ?></td><td><?= $row['result']==='accepted' ? 'Accepté' : 'Refusé' ?></td></tr><?php endforeach; ?></tbody><?php endif; ?>
</table></div><?php if (!$history['rows']): ?><p class="empty">Aucun élément enregistré.</p><?php endif; ?>
<?php if ($type==='subscriptions'): ?><p class="form-hint">Les dates, statuts et noms de formules correspondent aux valeurs actuelles, pas à un état historique reconstitué.</p><?php elseif ($type==='payments'): ?><p class="form-hint">Le montant remboursé reflète les remboursements enregistrés à ce jour. Les ventes boutique ne figurent pas ici.</p><?php else: ?><p class="form-hint">Les scans de cartes inconnues ne sont pas associés à une fiche. Ces données sont sensibles : ne les communiquez qu’aux personnes autorisées.</p><?php endif; ?>
<nav class="pagination" aria-label="Pages de l’historique"><?php if ($history['page']>1): ?><a href="<?= e($url($history['page']-1)) ?>">← Précédent</a><?php endif; ?><span>Page <?= (int)$history['page'] ?> / <?= (int)$history['pages'] ?></span><?php if ($history['page']<$history['pages']): ?><a href="<?= e($url($history['page']+1)) ?>">Suivant →</a><?php endif; ?></nav></section>
<?php require __DIR__.'/management_footer.php'; ?>
